/**
 * Game type definitions and metadata
 */

export const GAME_TYPES = {
  WEREWOLF: 'werewolf',
  MAFIA: 'mafia',
  AMONG_US: 'among_us'
  // Add more games here in the future
};

export const GAME_METADATA = {
  [GAME_TYPES.WEREWOLF]: {
    id: GAME_TYPES.WEREWOLF,
    name: 'Tit Albert Werewolf',
    description: 'A social deduction game where villagers try to eliminate the werewolves among them.',
    icon: '🐺',
    minPlayers: 4,
    maxPlayers: 15,
    setupRoute: '/games/werewolf/setup',
    joinRoute: '/games/werewolf/join',
    color: '#667eea'
  }
  // Future games can be added here
  // [GAME_TYPES.MAFIA]: {
  //   id: GAME_TYPES.MAFIA,
  //   name: 'Mafia',
  //   description: 'Classic mafia game...',
  //   icon: '🕴️',
  //   minPlayers: 5,
  //   maxPlayers: 12,
  //   setupRoute: '/games/mafia/setup',
  //   joinRoute: '/games/mafia/join',
  //   color: '#ff6b6b'
  // }
};

export const getGameMetadata = (gameType) => {
  return GAME_METADATA[gameType] || null;
};
